from produire import produire,paras,steps,table
from infection import traitements
parts=[
('La {méningite bactérienne aiguë} est une infection des méninges et du liquide cérébrospinal. Elle constitue une urgence vitale. La raideur de nuque peut manquer, notamment chez le nourrisson ou la personne âgée.',paras('L’atteinte peut s’accompagner de sepsis ou d’encéphalopathie. Une maladie méningococcique peut provoquer un choc sans syndrome méningé complet.', 'La clinique seule ne permet pas de distinguer sûrement une méningite bactérienne d’une forme virale. Le diagnostic et le traitement urgent avancent en parallèle.')),
('Le {terrain oriente les agents et les risques}. Pneumocoque et méningocoque sont des causes importantes. Âge, grossesse, immunodépression et portes d’entrée modifient les hypothèses.',paras('Rechercher vaccination, asplénie, déficit immunitaire, fuite de liquide cérébrospinal, implant cochléaire, infection ORL et voyage ou contage. Le nouveau-né relève d’un protocole distinct.', 'Listeria doit être envisagée notamment chez des patients plus âgés, immunodéprimés ou enceintes. Les pourcentages d’une série étrangère ou ancienne ne sont pas une répartition suisse actuelle.')),
('La {réponse inflammatoire méningée} participe aux lésions. Elle peut provoquer œdème, altération de perfusion et atteinte des nerfs crâniens. Le sepsis ajoute une menace circulatoire et systémique.',paras('Les bactéries peuvent atteindre les méninges par voie sanguine ou à partir d’un foyer contigu. L’inflammation de l’espace sous-arachnoïdien explique céphalée, photophobie et raideur.', 'La corticothérapie adjuvante vise une part de cette réponse, sans remplacer l’antibiotique. Une prise en charge rapide vise aussi à prévenir décès et séquelles auditives ou neurologiques.')),
('Le {tri reconnaît l’urgence sans attendre tous les signes}. Fièvre, céphalée, raideur et altération de conscience forment une association très évocatrice. Purpura extensif, choc, convulsion ou déficit imposent une prise en charge immédiate.',paras('Hors hôpital, organiser le transfert urgent, avec appel au 144 si nécessaire. Rechercher sepsis, protéger les voies aériennes et traiter l’instabilité avant tout geste diagnostique non sûr.', 'Ne pas attendre un scanner, une ponction lombaire ou les résultats biologiques si cela retarde une antibiothérapie nécessaire. Un antipyrétique peut masquer la fièvre.')),
('L’{anamnèse cherche vitesse d’évolution et terrain}. Préciser début, céphalée, vomissements, photophobie et comportement inhabituel. Demander antibiotiques déjà reçus, allergies et traitement anticoagulant.',paras('Chez l’enfant, rechercher mauvaise alimentation, irritabilité, somnolence ou hypotonie. Chez la personne âgée, une confusion peut dominer.', 'Interroger sur infection ORL, traumatisme, neurochirurgie, immunosuppression, grossesse et contacts. Une antibiothérapie préalable peut modifier la culture et l’aspect du liquide sans exclure une infection bactérienne.')),
('L’{examen associe état général et neurologie}. Contrôler constantes, perfusion, conscience, pupilles et peau. Chercher déficit, convulsions et signes méningés sans geste forcé.',paras('L’absence de signes de Kernig ou Brudzinski ne permet pas d’écarter la méningite. Examiner toute la peau et les conjonctives pour un purpura, en tenant compte de sa visibilité variable selon la pigmentation.', 'Évaluer immédiatement les éléments qui rendent la ponction lombaire dangereuse : instabilité, troubles de coagulation, signes de lésion expansive ou d’hypertension intracrânienne.')),
('L’{approche syndromique associe méningite, encéphalite et sepsis}. Une altération de conscience ou une convulsion peut traduire une atteinte cérébrale associée. D’autres urgences peuvent produire un méningisme.',table(['Présentation','Conséquence'],[['Syndrome méningé fébrile.','Méningite bactérienne à traiter si suspectée, sans discrimination clinique fiable avec une forme virale.'],['Purpura, choc, défaillance.','Maladie méningococcique ou autre sepsis ; stabiliser et traiter immédiatement.'],['Céphalée en coup de tonnerre.','Rechercher aussi hémorragie ou cause vasculaire.'],['Douleur cervicale haute inflammatoire.','Dent couronnée possible, mais ne pas l’utiliser pour exclure une infection sans bilan.']])) ,
('Le {diagnostic réunit clinique et microbiologie}. La ponction lombaire est centrale lorsqu’elle est sûre. Hémocultures et autres analyses complètent la recherche.',paras('Le liquide est analysé pour cellules, protéines, glucose comparé à une glycémie, examen direct, culture et PCR pertinentes. Une prédominance de polynucléaires et un glucose bas sont évocateurs, mais aucun profil isolé ne suffit.', 'Une forme débutante ou partiellement traitée peut présenter un profil atypique. Des marqueurs inflammatoires sanguins normaux ou une culture négative après antibiotiques n’excluent pas à eux seuls la maladie.')),
('Les {examens ne doivent pas retarder le traitement}. Prélever rapidement les hémocultures et réaliser la ponction si elle est sûre et immédiatement accessible. L’imagerie avant ponction n’est pas systématique.',paras('Imagerie préalable si suspicion de lésion expansive, déficit focal, anomalie pupillaire ou altération importante ou rapidement progressive de conscience selon le protocole. Un scanner rassurant ne supprime pas toutes les contre-indications cliniques.', 'Stabiliser auparavant voie aérienne, respiration, choc, convulsions non contrôlées et risque hémorragique. Ne pas ponctionner sur infection locale ou devant purpura extensif rapidement progressif. Si la ponction est différée, traiter après prélèvements sanguins sans attendre l’imagerie.')),
('L’{algorithme fait primer le temps thérapeutique}. La suspicion suffit à déclencher la filière urgente. La preuve microbiologique adapte ensuite le traitement.',steps('Reconnaître syndrome compatible, sepsis et signes neurologiques ; stabiliser.', 'Prélèvements sanguins rapides et ponction lombaire seulement si sûre et sans délai dangereux.', 'Antibiothérapie intraveineuse immédiate adaptée ; corticothérapie adjuvante selon indication, sans retarder l’antibiotique.', 'Imagerie ou autres investigations si nécessaires ; surveiller étroitement.', 'Adapter au germe, aux résistances et au terrain ; organiser prévention des contacts et suivi des séquelles.')),
('La {prise en charge suisse est hospitalière et urgente}. Une céphalosporine adaptée à dose méningée est souvent au cœur du traitement initial. Ajouter la couverture de Listeria ou d’autres résistances quand le terrain et l’épidémiologie l’imposent.',paras('La synthèse suisse de 2016 vise un traitement dans les trente minutes ; NICE 2024 demande une administration dès suspicion, dans l’heure suivant l’arrivée. Ces repères ne constituent pas une autorisation d’attendre, notamment en cas de choc.', '@@MEDICAMENTS@@', 'La céphalosporine seule ne couvre pas Listeria. Une couverture supplémentaire du pneumocoque résistant peut être requise selon contexte local ou voyage ; choix, dose et surveillance relèvent du protocole infectiologique. Les allergies sévères nécessitent une alternative spécialisée, sans improvisation.', 'Surveiller défaillances, convulsions, hydrocéphalie et complications vasculaires. La durée dépend du pathogène et de l’évolution ; les chiffres d’une notice ne deviennent pas une durée universelle.')),
('La {prévention et le suivi} commencent avant la sortie. Organiser l’évaluation auditive, neurologique et fonctionnelle. Vaccination et mesures autour d’un cas dépendent de l’agent identifié.',paras('En cas de méningocoque suspecté, appliquer les précautions de transmission adaptées et coordonner rapidement avec l’hygiène hospitalière et les autorités cantonales. La prophylaxie des contacts proches est décidée selon exposition ; elle n’est pas une antibiothérapie de tous les contacts occasionnels.', 'Rechercher séquelles auditives, troubles cognitifs, fatigue, difficultés scolaires ou professionnelles. Donner un plan de suivi et vérifier les vaccinations suisses recommandées selon âge et risques.')),
('Le {point clé} est de ne pas perdre de temps devant la suspicion. L’absence de raideur ou de purpura ne rassure pas suffisamment. La ponction éclaire le diagnostic, mais ne doit pas retarder l’antibiothérapie lorsque son délai est dangereux.',paras('Le diagnostic clinique incomplet et les résultats initiaux négatifs doivent être interprétés dans le contexte. Les soins urgents et l’adaptation microbiologique sont deux étapes complémentaires.'))]
quiz=[('La triade doit-elle être complète ?','Non.'),('Un Kernig négatif exclut-il la maladie ?','Non.'),('Un purpura est-il obligatoire ?','Non.'),('Faut-il un scanner avant chaque ponction ?','Non.'),('Que faire si la ponction retarde dangereusement le traitement ?','Prélever rapidement le sang et commencer les antibiotiques sans l’attendre.'),('Peut-on ponctionner un patient en choc non stabilisé ?','Non, stabiliser d’abord.'),('La culture négative après antibiotique exclut-elle l’infection ?','Non.'),('Pourquoi mesurer la glycémie avec le glucose du liquide ?','Pour interpréter leur rapport.'),('La ceftriaxone couvre-t-elle Listeria ?','Non.'),('Un nouveau-né reçoit-il automatiquement le schéma de l’enfant ?','Non, contre-indications et protocole spécifiques.'),('La dexaméthasone doit-elle retarder l’antibiotique ?','Non.'),('La durée est-elle identique pour tous les germes ?','Non.'),('Quel suivi sensoriel est essentiel ?','L’évaluation auditive.'),('Tous les contacts occasionnels reçoivent-ils une prophylaxie ?','Non, elle est ciblée selon exposition et recommandations de santé publique.')]
produire(5,parts,quiz,(6,8,16,17,18,19),traitements)
